/// The scope of an action. The scope is the context in which an action
/// must be executed.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Scope {
    App,
    Surface,
}

/// Formatting and hashing of an action's parameter value. This is the Rust
/// counterpart of the comptime type switches in `Action.formatValue` and
/// `Action.hashIncremental`.
trait ActionValue {
    /// `formatValue`: write the value in the format used by `parse`.
    fn format_value(&self, out: &mut Vec<u8>);

    /// Hash the value like `std.hash.autoHashStrat(.DeepRecursive)` (floats
    /// are hashed by their bits).
    fn hash_value(&self, hasher: &mut Wyhash);
}

/// Parsing of an action's parameter. This is the Rust counterpart of the
/// comptime type switch in `Action.parse`/`parseParameter`.
trait ActionParam: ActionValue + Sized {
    /// `param` is the text after the colon, or `None` if the action had no
    /// colon (in which case types with a `default` decl use it).
    fn parse_param(param: Option<&[u8]>) -> Result<Self, Error>;
}

// []const u8
impl ActionValue for Vec<u8> {
    fn format_value(&self, out: &mut Vec<u8>) {
        out.extend_from_slice(self);
    }

    fn hash_value(&self, hasher: &mut Wyhash) {
        // Slice (DeepRecursive): the elements, then the length.
        hasher.update(self);
        hasher.update(&self.len().to_ne_bytes());
    }
}

impl ActionParam for Vec<u8> {
    fn parse_param(param: Option<&[u8]>) -> Result<Self, Error> {
        param.map(|p| p.to_vec()).ok_or(Error::InvalidFormat)
    }
}

macro_rules! action_int_param {
    ($($t:ty),* $(,)?) => {$(
        impl ActionValue for $t {
            fn format_value(&self, out: &mut Vec<u8>) {
                out.extend_from_slice(self.to_string().as_bytes());
            }

            fn hash_value(&self, hasher: &mut Wyhash) {
                hasher.update(&self.to_ne_bytes());
            }
        }

        impl ActionParam for $t {
            fn parse_param(param: Option<&[u8]>) -> Result<Self, Error> {
                parse_int::<$t>(param.ok_or(Error::InvalidFormat)?)
            }
        }
    )*};
}

action_int_param!(i16, u16, usize, isize);

impl ActionValue for f32 {
    fn format_value(&self, out: &mut Vec<u8>) {
        format_float(*self, out);
    }

    fn hash_value(&self, hasher: &mut Wyhash) {
        // Floats are hashed by their bits. This is totally not
        // portable and there are edge cases such as NaNs and
        // signed zeros but these are not cases we expect for
        // our bindings.
        hasher.update(&self.to_bits().to_ne_bytes());
    }
}

impl ActionParam for f32 {
    fn parse_param(param: Option<&[u8]>) -> Result<Self, Error> {
        parse_float(param.ok_or(Error::InvalidFormat)?)
    }
}

/// Zig `std.fmt.parseInt(T, value, 10)`: an optional `+`/`-` sign followed
/// by decimal digits, with single or repeated `_` separators allowed
/// between digits (not leading or trailing).
fn parse_int<T: TryFrom<i128>>(value: &[u8]) -> Result<T, Error> {
    let (neg, digits) = match value.first() {
        None => return Err(Error::InvalidFormat),
        Some(b'+') => (false, &value[1..]),
        Some(b'-') => (true, &value[1..]),
        Some(_) => (false, value),
    };
    if digits.is_empty() || digits[0] == b'_' || digits[digits.len() - 1] == b'_' {
        return Err(Error::InvalidFormat);
    }

    let mut acc: i128 = 0;
    for &c in digits {
        if c == b'_' {
            continue;
        }
        if !c.is_ascii_digit() {
            return Err(Error::InvalidFormat);
        }
        let digit = (c - b'0') as i128;
        acc = acc
            .checked_mul(10)
            .and_then(|a| if neg { a.checked_sub(digit) } else { a.checked_add(digit) })
            .ok_or(Error::InvalidFormat)?;
    }

    T::try_from(acc).map_err(|_| Error::InvalidFormat)
}

/// Zig `std.fmt.parseFloat(f32, value)`: optional sign, `inf`/`infinity`/
/// `nan` (case-insensitive), hexadecimal floats (`0x1.8p3`) and decimal
/// floats with optional exponent. `_` separators are allowed only between
/// two digits.
fn parse_float(value: &[u8]) -> Result<f32, Error> {
    const ERR: Error = Error::InvalidFormat;
    let (neg, body) = match value.first() {
        None => return Err(ERR),
        Some(b'+') => (false, &value[1..]),
        Some(b'-') => (true, &value[1..]),
        Some(_) => (false, value),
    };
    if body.is_empty() {
        return Err(ERR);
    }
    let sign = if neg { -1.0f32 } else { 1.0f32 };

    // Special values
    if body.eq_ignore_ascii_case(b"inf") || body.eq_ignore_ascii_case(b"infinity") {
        return Ok(sign * f32::INFINITY);
    }
    if body.eq_ignore_ascii_case(b"nan") {
        return Ok(f32::NAN);
    }

    let hex = body.len() > 2 && body[0] == b'0' && (body[1] == b'x' || body[1] == b'X');
    let digits = if hex { &body[2..] } else { body };
    let is_digit = |c: u8| if hex { c.is_ascii_hexdigit() } else { c.is_ascii_digit() };

    // validUnderscores: every underscore must be between two digits.
    let mut cleaned: Vec<u8> = Vec::with_capacity(digits.len());
    let mut i = 0;
    while i < digits.len() {
        let c = digits[i];
        if c == b'_' {
            if i == 0 || i + 1 == digits.len() || !is_digit(digits[i - 1]) || !is_digit(digits[i + 1]) {
                return Err(ERR);
            }
        } else {
            cleaned.push(c);
        }
        i += 1;
    }

    if hex {
        return parse_hex_float(&cleaned).map(|v| sign * v).ok_or(ERR);
    }

    // Decimal: the mantissa must start with a digit or a dot (the sign
    // was already consumed above).
    match cleaned.first() {
        Some(c) if c.is_ascii_digit() || *c == b'.' => {}
        _ => return Err(ERR),
    }
    let s = std::str::from_utf8(&cleaned).map_err(|_| ERR)?;
    // Rust's parser accepts exactly the remaining decimal grammar
    // (digits, optional fraction, optional exponent).
    let v: f32 = s.parse().map_err(|_| ERR)?;
    Ok(sign * v)
}

/// Parse the part of a hexadecimal float after `0x`: hex digits with an
/// optional fraction and an optional binary exponent (`p`/`P`).
fn parse_hex_float(s: &[u8]) -> Option<f32> {
    let mut mantissa: f64 = 0.0;
    let mut exp: i64 = 0;
    let mut any_digit = false;
    let mut i = 0;
    let mut seen_dot = false;
    while i < s.len() {
        let c = s[i];
        if c == b'.' {
            if seen_dot {
                return None;
            }
            seen_dot = true;
        } else if let Some(d) = (c as char).to_digit(16) {
            mantissa = mantissa * 16.0 + d as f64;
            if seen_dot {
                exp -= 4;
            }
            any_digit = true;
        } else {
            break;
        }
        i += 1;
    }
    if !any_digit {
        return None;
    }
    if i < s.len() {
        if s[i] != b'p' && s[i] != b'P' {
            return None;
        }
        let e: i64 = parse_int::<i64>(&s[i + 1..]).ok()?;
        exp = exp.checked_add(e)?;
    }
    let exp = exp.clamp(-4000, 4000) as i32;
    Some((mantissa * 2f64.powi(exp)) as f32)
}

/// Zig `{d}` formatting of a float.
fn format_float(v: f32, out: &mut Vec<u8>) {
    if v.is_nan() {
        out.extend_from_slice(b"nan");
    } else if v.is_infinite() {
        out.extend_from_slice(if v < 0.0 { b"-inf" } else { b"inf" });
    } else {
        out.extend_from_slice(v.to_string().as_bytes());
    }
}

/// Defines a parameter enum whose Zig tag names are used as config
/// strings (`std.meta.stringToEnum` / `{t}`).
macro_rules! action_enum {
    (
        $(#[$meta:meta])*
        pub enum $E:ident {
            $( $(#[$vmeta:meta])* $V:ident = $name:literal, )*
        }
    ) => {
        $(#[$meta])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        pub enum $E {
            $( $(#[$vmeta])* $V, )*
        }

        impl $E {
            /// All values in declaration order.
            pub const ALL: &'static [$E] = &[$($E::$V,)*];

            /// The Zig tag name (`@tagName`).
            pub const fn as_str(self) -> &'static str {
                match self {
                    $($E::$V => $name,)*
                }
            }

            /// `std.meta.stringToEnum`: an exact tag name match.
            pub fn from_tag_name(s: &[u8]) -> Option<$E> {
                $(if s == $name.as_bytes() {
                    return Some($E::$V);
                })*
                None
            }
        }

        impl fmt::Display for $E {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                f.write_str(self.as_str())
            }
        }

        impl ActionValue for $E {
            fn format_value(&self, out: &mut Vec<u8>) {
                out.extend_from_slice(self.as_str().as_bytes());
            }

            fn hash_value(&self, hasher: &mut Wyhash) {
                // Enums hash their (byte sized) integer tag.
                hasher.update(&[*self as u8]);
            }
        }
    };
}

/// `ActionParam` for a plain enum parameter, optionally with a `default`.
macro_rules! action_enum_param {
    ($E:ident) => {
        impl ActionParam for $E {
            fn parse_param(param: Option<&[u8]>) -> Result<Self, Error> {
                parse_enum::<$E>(param.ok_or(Error::InvalidFormat)?, $E::from_tag_name)
            }
        }
    };
    ($E:ident, default) => {
        impl ActionParam for $E {
            fn parse_param(param: Option<&[u8]>) -> Result<Self, Error> {
                match param {
                    None => Ok($E::DEFAULT),
                    Some(p) => parse_enum::<$E>(p, $E::from_tag_name),
                }
            }
        }

        impl Default for $E {
            fn default() -> Self {
                $E::DEFAULT
            }
        }
    };
}

/// `Action.parseEnum`
fn parse_enum<T>(value: &[u8], f: fn(&[u8]) -> Option<T>) -> Result<T, Error> {
    f(value).ok_or(Error::InvalidFormat)
}

action_enum! {
    /// `Action.CrashThread`
    pub enum CrashThread {
        Main = "main",
        Io = "io",
        Render = "render",
    }
}
action_enum_param!(CrashThread);

/// `Action.CursorKey`
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct CursorKey {
    pub normal: Vec<u8>,
    pub application: Vec<u8>,
}

impl ActionValue for CursorKey {
    fn format_value(&self, _out: &mut Vec<u8>) {
        panic!("formatting not supported");
    }

    fn hash_value(&self, hasher: &mut Wyhash) {
        self.normal.hash_value(hasher);
        self.application.hash_value(hasher);
    }
}

impl ActionParam for CursorKey {
    fn parse_param(_param: Option<&[u8]>) -> Result<Self, Error> {
        // Cursor keys can't be set currently
        Err(Error::InvalidAction)
    }
}

