action_enum! {
    /// `Action.SplitFocusDirection`
    pub enum SplitFocusDirection {
        Previous = "previous",
        Next = "next",
        Up = "up",
        Left = "left",
        Down = "down",
        Right = "right",
    }
}

impl SplitFocusDirection {
    pub fn parse(input: &[u8]) -> Result<SplitFocusDirection, Error> {
        if let Some(v) = SplitFocusDirection::from_tag_name(input) {
            return Ok(v);
        }

        // For backwards compatibility we map "top" and "bottom" onto the enum
        // values "up" and "down"
        if input == b"top" {
            Ok(SplitFocusDirection::Up)
        } else if input == b"bottom" {
            Ok(SplitFocusDirection::Down)
        } else {
            Err(Error::InvalidFormat)
        }
    }
}

impl ActionParam for SplitFocusDirection {
    fn parse_param(param: Option<&[u8]>) -> Result<Self, Error> {
        // Fields can provide a custom "parse" function
        SplitFocusDirection::parse(param.ok_or(Error::InvalidFormat)?)
    }
}

action_enum! {
    /// `Action.SplitResizeDirection`
    pub enum SplitResizeDirection {
        Up = "up",
        Down = "down",
        Left = "left",
        Right = "right",
    }
}

action_enum! {
    /// `Action.GotoWindow`
    pub enum GotoWindow {
        Previous = "previous",
        Next = "next",
    }
}
action_enum_param!(GotoWindow);

/// `Action.SplitResizeParameter` (a Zig tuple).
pub type SplitResizeParameter = (SplitResizeDirection, u16);

impl ActionValue for SplitResizeParameter {
    fn format_value(&self, out: &mut Vec<u8>) {
        self.0.format_value(out);
        out.push(b',');
        self.1.format_value(out);
    }

    fn hash_value(&self, hasher: &mut Wyhash) {
        self.0.hash_value(hasher);
        self.1.hash_value(hasher);
    }
}

impl ActionParam for SplitResizeParameter {
    fn parse_param(param: Option<&[u8]>) -> Result<Self, Error> {
        let param = param.ok_or(Error::InvalidFormat)?;

        // Only tuples are supported to avoid ambiguity with field
        // ordering
        let mut it = param.split(|c| *c == b',');
        let dir = parse_enum(
            it.next().ok_or(Error::InvalidFormat)?,
            SplitResizeDirection::from_tag_name,
        )?;
        let amount = parse_int::<u16>(it.next().ok_or(Error::InvalidFormat)?)?;

        // If we have extra parameters it is an error
        if it.next().is_some() {
            return Err(Error::InvalidFormat);
        }

        Ok((dir, amount))
    }
}

