/// `Action.WriteScreen`
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct WriteScreen {
    pub action: WriteScreenAction,
    pub emit: WriteScreenFormat,
}

action_enum! {
    /// `Action.WriteScreen.Action`
    pub enum WriteScreenAction {
        Copy = "copy",
        Paste = "paste",
        Open = "open",
    }
}

action_enum! {
    /// `Action.WriteScreen.Format`
    pub enum WriteScreenFormat {
        Plain = "plain",
        Vt = "vt",
        Html = "html",
    }
}

impl WriteScreen {
    pub const COPY: WriteScreen = WriteScreen {
        action: WriteScreenAction::Copy,
        emit: WriteScreenFormat::Plain,
    };
    pub const PASTE: WriteScreen = WriteScreen {
        action: WriteScreenAction::Paste,
        emit: WriteScreenFormat::Plain,
    };
    pub const OPEN: WriteScreen = WriteScreen {
        action: WriteScreenAction::Open,
        emit: WriteScreenFormat::Plain,
    };

    pub fn parse(param: &[u8]) -> Result<WriteScreen, Error> {
        // If we don't have a `,`, default to the plain format. This is
        // also very important for backwards compatibility before Ghostty
        // 1.3 which didn't support output formats.
        let Some(idx) = memchr::memchr(b',', param) else {
            return Ok(WriteScreen {
                action: parse_enum(param, WriteScreenAction::from_tag_name)?,
                emit: WriteScreenFormat::Plain,
            });
        };

        Ok(WriteScreen {
            action: parse_enum(&param[..idx], WriteScreenAction::from_tag_name)?,
            emit: parse_enum(&param[idx + 1..], WriteScreenFormat::from_tag_name)?,
        })
    }
}

impl fmt::Display for WriteScreen {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{},{}", self.action, self.emit)
    }
}

impl ActionValue for WriteScreen {
    fn format_value(&self, out: &mut Vec<u8>) {
        out.extend_from_slice(self.to_string().as_bytes());
    }

    fn hash_value(&self, hasher: &mut Wyhash) {
        self.action.hash_value(hasher);
        self.emit.hash_value(hasher);
    }
}

impl ActionParam for WriteScreen {
    fn parse_param(param: Option<&[u8]>) -> Result<Self, Error> {
        WriteScreen::parse(param.ok_or(Error::InvalidFormat)?)
    }
}

