    #[test]
    fn parse_chain() {
        // Valid
        {
            let mut p = Parser::init(b"chain=new_tab").unwrap();
            assert_eq!(Some(Elem::Chain(Action::NewTab)), p.next().unwrap());
            assert_eq!(None, p.next().unwrap());
        }

        // Chain can't have flags
        assert_eq!(
            Error::InvalidFormat,
            Parser::init(b"global:chain=ignore").unwrap_err()
        );

        // Chain can't be part of a sequence
        {
            let mut p = Parser::init(b"a>chain=ignore").unwrap();
            let _ = p.next().unwrap();
            assert_eq!(Err(Error::InvalidFormat), p.next());
        }
    }

    #[test]
    fn sequence_iterator() {
        // single character
        {
            let mut it = SequenceIterator { input: b"a", i: 0 };
            assert_eq!(uni('a'), it.next().unwrap().unwrap());
            assert_eq!(None, it.next().unwrap());
        }

        // multi character
        {
            let mut it = SequenceIterator { input: b"a>b", i: 0 };
            assert_eq!(uni('a'), it.next().unwrap().unwrap());
            assert_eq!(uni('b'), it.next().unwrap().unwrap());
            assert_eq!(None, it.next().unwrap());
        }

        // empty
        {
            let mut it = SequenceIterator { input: b"", i: 0 };
            assert_eq!(Err(Error::InvalidFormat), it.next());
        }

        // empty starting sequence
        {
            let mut it = SequenceIterator { input: b">a", i: 0 };
            assert_eq!(Err(Error::InvalidFormat), it.next());
        }

        // empty ending sequence
        {
            let mut it = SequenceIterator { input: b"a>", i: 0 };
            assert_eq!(uni('a'), it.next().unwrap().unwrap());
            assert_eq!(Err(Error::InvalidFormat), it.next());
        }
    }

    #[test]
    fn parse_sequences() {
        // single character
        {
            let mut p = Parser::init(b"ctrl+a=ignore").unwrap();
            assert_eq!(
                Elem::Binding(bind(uni_m('a', m(|m| m.ctrl = true)), Action::Ignore)),
                p.next().unwrap().unwrap()
            );
            assert_eq!(None, p.next().unwrap());
        }

        // sequence
        {
            let mut p = Parser::init(b"a>b=ignore").unwrap();
            assert_eq!(Elem::Leader(uni('a')), p.next().unwrap().unwrap());
            assert_eq!(
                Elem::Binding(bind(uni('b'), Action::Ignore)),
                p.next().unwrap().unwrap()
            );
            assert_eq!(None, p.next().unwrap());
        }
    }

    #[test]
    fn set_parse_and_put_typical_binding() {
        let mut s = Set::default();

        s.parse_and_put(b"a=new_window").unwrap();

        // Creates forward mapping
        {
            let action = leaf(s.get(uni('a')).unwrap().value_ptr);
            assert_eq!(Action::NewWindow, action.action);
            assert_eq!(Flags::default(), action.flags);
        }

        // Creates reverse mapping
        {
            let trigger = s.get_trigger(&Action::NewWindow).unwrap();
            assert_eq!('a' as u32, unicode_of(trigger));
        }

        // Sets up the chain parent properly
        assert!(s.chain_parent().is_some());
        assert_eq!("a", s.chain_parent().unwrap().key_ptr.to_string());
    }

