    #[test]
    fn action_key_round_trip() {
        assert_eq!(88, ActionKey::ALL.len());
        for &k in ActionKey::ALL {
            assert_eq!(Some(k), ActionKey::from_tag_name(k.as_str().as_bytes()));
            assert_eq!(k.as_str().as_bytes(), k.as_cstr().to_bytes());
            assert!(!k.doc_lines().is_empty(), "{k} has no docs");
        }
    }

    #[test]
    fn action_scoped() {
        assert_eq!(Some(ScopedApp::Quit), Action::Quit.scoped_app());
        assert_eq!(None, Action::Quit.scoped_surface());
        assert_eq!(
            Some(ScopedSurface::NewSplit(SplitDirection::Left)),
            Action::NewSplit(SplitDirection::Left).scoped_surface()
        );
        assert_eq!(None, Action::NewSplit(SplitDirection::Left).scoped_app());
        assert_eq!(Scope::App, Action::NewWindow.scope());
        assert_eq!(Scope::Surface, Action::NewTab.scope());
    }

    #[test]
    fn action_format_parse_round_trip() {
        for input in [
            "ignore",
            "csi:0m",
            "increase_font_size:1.5",
            "set_font_size:13",
            "scroll_page_lines:-10",
            "goto_tab:1",
            "move_tab:-1",
            "resize_split:up,10",
            "new_split:right",
            "write_scrollback_file:open,vt",
            "close_tab:other",
        ] {
            let a = Action::parse(input.as_bytes()).unwrap();
            assert_eq!(input, a.to_string());
        }

        // Zig parseInt/parseFloat specifics
        assert_eq!(Action::GotoTab(1000), Action::parse(b"goto_tab:1_000").unwrap());
        assert_eq!(Action::GotoTab(0), Action::parse(b"goto_tab:-0").unwrap());
        assert_eq!(Err(Error::InvalidFormat), Action::parse(b"goto_tab:-1"));
        assert_eq!(Err(Error::InvalidFormat), Action::parse(b"goto_tab:_1"));
        assert_eq!(
            Action::SetFontSize(12.0),
            Action::parse(b"set_font_size:0x1.8p3").unwrap()
        );
        assert_eq!(Err(Error::InvalidFormat), Action::parse(b"set_font_size:+-1"));
        assert_eq!(Err(Error::InvalidAction), Action::parse(b"cursor_key"));
    }

    #[test]
    fn trigger_format() {
        let t = Trigger::parse(b"shift+ctrl+super+alt+key_a").unwrap();
        assert_eq!("super+ctrl+alt+shift+key_a", t.to_string());
        assert_eq!("ö", Trigger::parse("ö".as_bytes()).unwrap().to_string());
        assert_eq!("catch_all", Trigger::parse(b"catch_all").unwrap().to_string());
    }
